using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddHttpClient();
builder.Services.AddSingleton<Notebook>();

builder.Services.AddChatClient(chatClientBuilder =>
    chatClientBuilder.UseOpenAIChatClient(
        builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18"));

builder.Services.AddSingleton(sp =>
{
    var chatClient = sp.GetRequiredService<IChatClient>();
    var notebook = sp.GetRequiredService<Notebook>();
    var httpClientFactory = sp.GetRequiredService<IHttpClientFactory>();
    var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

    var tools = new List<AITool>
    {
        AIFunctionFactory.Create(
            ([Description("The search query to look up on the web")] string query) =>
                WebSearchAsync(httpClientFactory, query),
            "web_search",
            "Searches the web for information on a given query and returns relevant results."),

        AIFunctionFactory.Create(
            ([Description("A concise title for the note")] string title,
             [Description("The content/body of the note")] string content) =>
                notebook.SaveNote(title, content),
            "save_note",
            "Saves a research note with a title and content for later reference."),

        AIFunctionFactory.Create(
            () => notebook.GetAllNotes(),
            "get_notes",
            "Retrieves all previously saved research notes.")
    };

    return new ChatClientAgent(
        chatClient,
        instructions: """
            You are a research agent. When given a topic, you:
            1. Search the web for relevant information using the web_search tool (perform multiple searches with different queries to get broad coverage).
            2. Save important findings as notes using the save_note tool.
            3. After gathering enough information, review your notes with get_notes and provide a comprehensive summary.

            Always cite your sources. Be thorough but concise.
            """,
        name: "ResearchAgent",
        description: "An agent that researches topics by searching the web and summarizing findings.",
        tools: tools,
        loggerFactory: loggerFactory);
});

using var host = builder.Build();

var agent = host.Services.GetRequiredService<ChatClientAgent>();
var notebook = host.Services.GetRequiredService<Notebook>();

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       Research Agent (MAF)           ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║ Enter a topic to research, or       ║");
Console.WriteLine("║ type 'quit' to exit.                ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.Write("Research topic> ");
    var topic = Console.ReadLine()?.Trim();

    if (string.IsNullOrEmpty(topic))
        continue;

    if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    Console.WriteLine($"\nResearching: {topic}\n");

    try
    {
        using var session = await agent.CreateSessionAsync();
        var response = await agent.RunAsync(
            $"Research the following topic and provide a comprehensive summary: {topic}",
            session,
            new ChatClientAgentRunOptions(new ChatOptions
            {
                Temperature = 0f,
                MaxOutputTokens = 2048,
            }));

        Console.WriteLine("━━━ Research Summary ━━━");
        Console.WriteLine(response.Text);
        Console.WriteLine("━━━━━━━━━━━━━━━━━━━━━━━━\n");

        if (response.Usage is { } usage)
        {
            Console.WriteLine(
                $"[Tokens — input: {usage.InputTokenCount}, output: {usage.OutputTokenCount}, total: {usage.TotalTokenCount}]\n");
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error: {ex.Message}\n");
    }
}

Console.WriteLine("Goodbye!");

static async Task<string> WebSearchAsync(IHttpClientFactory httpClientFactory, string query)
{
    using var httpClient = httpClientFactory.CreateClient();
    httpClient.DefaultRequestHeaders.UserAgent.ParseAdd(
        "ResearchAgent/1.0 (compatible; research bot)");

    try
    {
        // Use DuckDuckGo Instant Answer API (no key required)
        var encodedQuery = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";

        var result = await httpClient.GetFromJsonAsync<JsonElement>(url);

        var parts = new List<string>();

        var abstractText = result.GetProperty("AbstractText").GetString();
        var abstractSource = result.GetProperty("AbstractSource").GetString();
        var abstractUrl = result.GetProperty("AbstractURL").GetString();

        if (!string.IsNullOrWhiteSpace(abstractText))
        {
            parts.Add($"## Summary from {abstractSource}\n{abstractText}\nSource: {abstractUrl}");
        }

        if (result.TryGetProperty("RelatedTopics", out var topics))
        {
            var count = 0;
            foreach (var topic in topics.EnumerateArray())
            {
                if (count >= 5) break;

                var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                var topicUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;

                if (!string.IsNullOrWhiteSpace(text))
                {
                    parts.Add($"- {text} ({topicUrl})");
                    count++;
                }
            }
        }

        if (parts.Count == 0)
        {
            parts.Add($"No detailed results found for '{query}'. Try rephrasing the search.");
        }

        return string.Join("\n\n", parts);
    }
    catch (Exception ex)
    {
        return $"Search failed for '{query}': {ex.Message}";
    }
}

/// <summary>
/// Simple in-memory notebook for the agent to store research findings.
/// </summary>
sealed class Notebook
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public string SaveNote(string title, string content)
    {
        _notes.Add((title, content, DateTime.UtcNow));
        return $"Note saved: '{title}' (total notes: {_notes.Count})";
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"### Note {i + 1}: {n.Title}\n{n.Content}\n[Saved at {n.Timestamp:u}]"));
    }

    public void Clear() => _notes.Clear();
}

