130. // Web search tool implementation (DuckDuckGo Instant Answer API — no key)
131. // ---------------------------------------------------------------------------
132. static async Task<string> WebSearchAsync(IHttpClientFactory httpClientFactory, string query)
133. {
134.     using var httpClient = httpClientFactory.CreateClient();
135.     httpClient.DefaultRequestHeaders.UserAgent.ParseAdd(
136.         "ResearchAgent/1.0 (compatible; research bot)");
137. 
138.     try
139.     {
140.         var encodedQuery = Uri.EscapeDataString(query);
141.         var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";
142. 
143.         var result = await httpClient.GetFromJsonAsync<JsonElement>(url);
144. 
145.         var parts = new List<string>();
146. 
147.         var abstractText = result.GetProperty("AbstractText").GetString();
148.         var abstractSource = result.GetProperty("AbstractSource").GetString();
149.         var abstractUrl = result.GetProperty("AbstractURL").GetString();
150. 
151.         if (!string.IsNullOrWhiteSpace(abstractText))
152.         {
153.             parts.Add($"## Summary from {abstractSource}\n{abstractText}\nSource: {abstractUrl}");
154.         }
155. 
156.         if (result.TryGetProperty("RelatedTopics", out var topics))
157.         {
158.             var count = 0;
159.             foreach (var topicItem in topics.EnumerateArray())
160.             {
161.                 if (count >= 5) break;
162. 
163.                 var text = topicItem.TryGetProperty("Text", out var t) ? t.GetString() : null;
164.                 var topicUrl = topicItem.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
165. 
166.                 if (!string.IsNullOrWhiteSpace(text))
167.                 {
168.                     parts.Add($"- {text} ({topicUrl})");
169.                     count++;
170.                 }
171.             }
172.         }
173. 
174.         if (parts.Count == 0)
175.         {
176.             parts.Add($"No detailed results found for '{query}'. Try rephrasing the search.");
177.         }
178. 
179.         return string.Join("\n\n", parts);
180.     }
181.     catch (Exception ex)
182.     {
183.         return $"Search failed for '{query}': {ex.Message}";
184.     }
185. }
