187. /// <summary>
188. /// Simple in-memory notebook for the agent to store research findings.
189. /// </summary>
190. sealed class Notebook
191. {
192.     private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];
193. 
194.     public string SaveNote(string title, string content)
195.     {
196.         _notes.Add((title, content, DateTime.UtcNow));
197.         return $"Note saved: '{title}' (total notes: {_notes.Count})";
198.     }
199. 
200.     public string GetAllNotes()
201.     {
202.         if (_notes.Count == 0)
203.             return "No notes saved yet.";
204. 
205.         return string.Join("\n\n", _notes.Select((n, i) =>
206.             $"### Note {i + 1}: {n.Title}\n{n.Content}\n[Saved at {n.Timestamp:u}]"));
207.     }
208. 
209.     public void Clear() => _notes.Clear();
210. }
