 static async Task<string> WebSearchAsync(IHttpClientFactory httpClientFactory, string query)
 {
     using var httpClient = httpClientFactory.CreateClient();
     httpClient.DefaultRequestHeaders.UserAgent.ParseAdd(
         "ResearchAgent/1.0 (compatible; research bot)");

